import axios from 'axios';
import { API_CONFIG } from '@/config/config';
import { ElMessage } from 'element-plus';

export const chatModule = {
  namespaced: true,
  state: {
    recentPrivateChats: [],  // 最近单聊（私聊）
    recentGroupChats: [],    // 最近群聊（单独管理）
    joinedGroups: []         // 已加入的群聊列表
  },
  mutations: {
    // 添加或更新私聊记录
    ADD_PRIVATE_CHAT(state, chat) {
      const chatId = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
      const existingIndex = state.recentPrivateChats.findIndex(item => 
        typeof item.id === 'string' ? parseInt(item.id, 10) === chatId : item.id === chatId
      );
      
      if (existingIndex !== -1) {
        state.recentPrivateChats.splice(existingIndex, 1);
      }
      
      state.recentPrivateChats.unshift({ ...chat, id: chatId, isGroup: false });
      
      if (state.recentPrivateChats.length > 50) {
        state.recentPrivateChats.pop();
      }
    },
    
    // 添加或更新群聊记录（仅用于最近群聊）
    ADD_GROUP_CHAT(state, chat) {
      const chatId = typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id;
      const existingIndex = state.recentGroupChats.findIndex(item => 
        typeof item.id === 'string' ? parseInt(item.id, 10) === chatId : item.id === chatId
      );
      
      if (existingIndex !== -1) {
        state.recentGroupChats.splice(existingIndex, 1);
      }
      
      state.recentGroupChats.unshift({ ...chat, id: chatId, isGroup: true });
      
      if (state.recentGroupChats.length > 50) {
        state.recentGroupChats.pop();
      }
    },
    
    // 初始化私聊记录
    INIT_PRIVATE_CHATS(state, chats) {
      state.recentPrivateChats = chats.map(chat => ({
        ...chat,
        id: typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id,
        isGroup: false
      })).sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
    },
    
    // 初始化群聊记录
    INIT_GROUP_CHATS(state, chats) {
      state.recentGroupChats = chats.map(chat => ({
        ...chat,
        id: typeof chat.id === 'string' ? parseInt(chat.id, 10) : chat.id,
        isGroup: true
      })).sort((a, b) => {
        const timeA = a.lastMessageTime ? new Date(a.lastMessageTime) : new Date(0);
        const timeB = b.lastMessageTime ? new Date(b.lastMessageTime) : new Date(0);
        return timeB - timeA;
      });
    },
    
    // 初始化已加入的群聊
    INIT_JOINED_GROUPS(state, groups) {
      state.joinedGroups = groups.map(group => ({
        ...group,
        id: typeof group.id === 'string' ? parseInt(group.id, 10) : group.id,
        isGroup: true
      }));
    },
    
    // 更新单个群聊信息（仅更新加入的群列表）
    UPDATE_JOINED_GROUP(state, updatedGroup) {
      const groupId = typeof updatedGroup.id === 'string' ? parseInt(updatedGroup.id, 10) : updatedGroup.id;
      const index = state.joinedGroups.findIndex(g => g.id === groupId);
      
      if (index !== -1) {
        state.joinedGroups.splice(index, 1, { ...state.joinedGroups[index], ...updatedGroup });
      } else {
        state.joinedGroups.push({ ...updatedGroup, id: groupId, isGroup: true });
      }
    },
    
    // 更新未读计数
    UPDATE_UNREAD_COUNT(state, { targetId, count, isGroup }) {
      const targetIdNum = typeof targetId === 'string' ? parseInt(targetId, 10) : targetId;
      
      if (isGroup) {
        // 更新群聊相关列表
        const groupIndex = state.recentGroupChats.findIndex(g => g.id === targetIdNum);
        if (groupIndex !== -1) {
          state.recentGroupChats[groupIndex].unreadCount = count;
        }
        
        const joinedGroupIndex = state.joinedGroups.findIndex(g => g.id === targetIdNum);
        if (joinedGroupIndex !== -1) {
          state.joinedGroups[joinedGroupIndex].unreadCount = count;
        }
      } else {
        // 更新私聊列表
        const privateIndex = state.recentPrivateChats.findIndex(p => p.id === targetIdNum);
        if (privateIndex !== -1) {
          state.recentPrivateChats[privateIndex].unreadCount = count;
        }
      }
    },
    
    // 清除所有聊天记录
    CLEAR_ALL_CHATS(state) {
      state.recentPrivateChats = [];
      state.recentGroupChats = [];
      state.joinedGroups = [];
    }
  },
  actions: {
    // 加载最近私聊列表
    async loadPrivateChats({ commit, rootState }) {
      try {
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/ws/chat/recent-private-chats/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        const formattedChats = response.data.map(chat => ({
          id: chat.target_id,
          username: chat.target_username,
          photo: chat.target_photo,
          lastMessage: chat.last_message,
          lastMessageTime: chat.last_message_time,
          unreadCount: chat.unread_count || 0,
          isGroup: false
        }));
        
        commit('INIT_PRIVATE_CHATS', formattedChats);
        return formattedChats;
      } catch (error) {
        console.error('加载最近私聊列表失败:', error);
        return [];
      }
    },
    
    // 加载最近群聊列表
    async loadGroupChats({ commit, rootState }) {
      try {
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/ws/chat/recent-group-chats/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        const formattedChats = response.data.map(chat => ({
          id: chat.group_id,
          username: chat.group_name,
          photo: chat.group_photo,
          lastMessage: chat.last_message,
          lastMessageTime: chat.last_message_time,
          unreadCount: chat.unread_count || 0,
          isGroup: true
        }));
        
        commit('INIT_GROUP_CHATS', formattedChats);
        return formattedChats;
      } catch (error) {
        console.error('加载最近群聊列表失败:', error);
        return [];
      }
    },
    
    // 加载已加入的群聊
    async loadJoinedGroups({ commit, rootState }) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法加载已加入的群聊');
          ElMessage.warning('请先登录');
          return [];
        }
        
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/get-joined-groups/${userId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        const formattedGroups = (response.data || []).map(group => ({
          id: group.group_id,
          username: group.group_name,
          photo: group.group_photo,
          lastMessage: group.last_message || '',
          lastMessageTime: group.last_message_time || new Date().toISOString(),
          unreadCount: group.unread_count || 0,
          members: group.members || [],
          membersCount: group.members_count || group.members?.length || 0,
          ownerId: group.owner_id
        }));
        
        commit('INIT_JOINED_GROUPS', formattedGroups);
        return formattedGroups;
      } catch (error) {
        console.error('加载已加入的群聊失败:', error);
        ElMessage.error('加载已加入的群聊失败，请重试');
        return [];
      }
    },
    
    // 刷新单个群聊信息
    async refreshJoinedGroup({ commit, rootState }, groupId) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法刷新群聊信息');
          return null;
        }
        
        const response = await axios.get(`${API_CONFIG.BASE_URL}/group/${groupId}`, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        if (response.data) {
          const updatedGroup = {
            id: groupId,
            ...response.data,
            isGroup: true
          };
          
          commit('UPDATE_JOINED_GROUP', updatedGroup);
          return updatedGroup;
        }
      } catch (error) {
        console.error(`刷新群聊 ${groupId} 信息失败:`, error);
        ElMessage.error('刷新群聊信息失败');
        return null;
      }
    },
    
    // 保存私聊记录
    async savePrivateChat({ rootState }, chatInfo) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法保存私聊记录');
          return;
        }
        
        const recentChatData = {
          user_id: rootState.user.id,
          target_id: chatInfo.id,
          target_username: chatInfo.username,
          target_photo: chatInfo.photo,
          last_message: chatInfo.lastMessage || '',
          last_message_time: chatInfo.lastMessageTime || new Date().toISOString(),
          unread_count: chatInfo.unreadCount || 0,
          is_group: false
        };
        
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/save-private-chat`, recentChatData, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
      } catch (error) {
        console.error('保存私聊记录失败:', error);
        throw error;
      }
    },
    
    // 保存群聊记录
    async saveGroupChat({ rootState }, chatInfo) {
      try {
        if (!rootState.user || !rootState.user.id) {
          console.log('用户未登录，无法保存群聊记录');
          return;
        }
        
        const recentChatData = {
          user_id: rootState.user.id,
          group_id: chatInfo.id,
          last_message: chatInfo.lastMessage || '',
          last_message_time: chatInfo.lastMessageTime || new Date().toISOString(),
          unread_count: chatInfo.unreadCount || 0
        };
        
        await axios.post(`${API_CONFIG.BASE_URL}/ws/chat/save-group-chat`, recentChatData, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
      } catch (error) {
        console.error('保存群聊记录失败:', error);
        throw error;
      }
    },
    
    // 清除未读计数
    async clearUnreadCount({ commit, rootState }, { targetId, isGroup }) {
      try {
        const userId = rootState.user.id;
        const endpoint = isGroup 
          ? `${API_CONFIG.BASE_URL}/ws/chat/clear-group-unread/${targetId}`
          : `${API_CONFIG.BASE_URL}/ws/chat/clear-private-unread/${targetId}`;
        
        await axios.post(endpoint, { user_id: userId }, {
          headers: { Authorization: `Bearer ${rootState.token}` }
        });
        
        commit('UPDATE_UNREAD_COUNT', { targetId, count: 0, isGroup });
      } catch (error) {
        console.error('清除未读计数失败:', error);
        throw error;
      }
    },
    
    // 登出时清除所有聊天记录
    async clearAllChats({ commit }) {
      commit('CLEAR_ALL_CHATS');
    },
    
    // 手动添加私聊到最近聊天
    async addPrivateToRecent({ commit, dispatch }, chatInfo) {
      commit('ADD_PRIVATE_CHAT', chatInfo);
      await dispatch('savePrivateChat', chatInfo);
    },
    
    // 手动添加群聊到最近聊天
    async addGroupToRecent({ commit, dispatch }, chatInfo) {
      commit('ADD_GROUP_CHAT', chatInfo);
      await dispatch('saveGroupChat', chatInfo);
    }
  },
  getters: {
    // 获取所有私聊
    getPrivateChats: state => state.recentPrivateChats,
    
    // 获取所有群聊（最近聊天的群聊）
    getGroupChats: state => state.recentGroupChats,
    
    // 获取已加入的群组
    getJoinedGroups: state => state.joinedGroups,
    
    // 获取私聊或群聊（根据ID和类型）
    getChatById: (state) => (id, isGroup = false) => {
      const idNum = typeof id === 'string' ? parseInt(id, 10) : id;
      return isGroup 
        ? state.recentGroupChats.find(chat => chat.id === idNum) || 
          state.joinedGroups.find(group => group.id === idNum)
        : state.recentPrivateChats.find(chat => chat.id === idNum);
    },
    
    // 获取总未读消息数
    getTotalUnreadCount: state => {
      const privateUnread = state.recentPrivateChats.reduce((sum, chat) => sum + (chat.unreadCount || 0), 0);
      const groupUnread = state.recentGroupChats.reduce((sum, chat) => sum + (chat.unreadCount || 0), 0);
      return privateUnread + groupUnread;
    },
    
    // 获取已加入的群组数量
    getJoinedGroupsCount: state => state.joinedGroups.length
  }
};

export default chatModule;
